  assert.ok(typeof text === 'string');
  assert.ok(text.includes('\n'));
  const lines = text.split('\n');
  assert.ok(lines.length >= 4); // at least: number, customer, line, total
});

test('renderInvoiceText with issued invoice and multiple lines', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 5 },
      { sku: 'PRINT-A3', qty: 2 },
    ],
  });
  const r2 = issueInvoice(r1.value, ['INV-2025-0001']);
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'INV-2025-0002');
  assert.equal(lines[1], 'Blue Fern Bakery');
  // 5 * 37 = 185 cents = €1.85
  assert.equal(lines[2], '5 x Printed flyer A4 (each) @ €0.37 = €1.85');
  // 2 * 249 = 498 cents = €4.98
  assert.equal(lines[3], '2 x Printed poster A3 (each) @ €2.49 = €4.98');
  // Check VAT and Total present
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
  assert.ok(text.includes('Due:'));
});

test('renderInvoiceText shows VAT line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // Should have: number, customer, product line, VAT line, total line, due line
  assert.ok(lines.length >= 5);
  const vatIndex = lines.findIndex((l) => l.startsWith('VAT: '));
  const totalIndex = lines.findIndex((l) => l.startsWith('Total: '));
  assert.ok(vatIndex >= 0);
  assert.ok(totalIndex > vatIndex);
});

test('renderInvoiceText with 0% VAT does not show charge', () => {
